	Date     string         `json:"date"` // YYYY-MM-DD
	Currency money.Currency `json:"currency"`
	Amount   int64          `json:"amount"`
	Payments int            `json:"payments"`
}

// Group is how a revenue report groups days into buckets.
type Group string

// Groups.
const (
	GroupDay   Group = "day"
	GroupWeek  Group = "week"
	GroupMonth Group = "month"
)

// Valid reports whether g is a known group.
func (g Group) Valid() bool { return g == GroupDay || g == GroupWeek || g == GroupMonth }

// Bucket is what an organization took in one day, week or month. Start is the bucket's first day (YYYY-MM-DD).
type Bucket struct {
	Start    string                   `json:"start"`
	Amounts  map[money.Currency]int64 `json:"amounts"`
	Payments int                      `json:"payments"`
}

// Report is an organization's revenue per bucket, with the days in the organization's time zone.
type Report struct {
	TimeZone string   `json:"time_zone"`
	Group    Group    `json:"group"`
	Buckets  []Bucket `json:"buckets"`
}

// Errors.
var (
	ErrInvalidDate  = errors.New("invalid date")
	ErrInvalidRange = errors.New("invalid date range")
	ErrInvalidGroup = errors.New("invalid group")
)

// MaxDays is the longest range a report covers.
const MaxDays = 366

// Revenue adds up the organization's succeeded payments per day and currency, from the day from to the day to (YYYY-MM-DD,
// both included). Days are days in the organization's time zone. The result is in date order, currencies in alphabetical
// order within a day; days without payments are left out.
func Revenue(st *store.Store, orgID, from, to string) ([]DayRevenue, error) {
	first, last, err := parseRange(from, to)
	if err != nil {
		return nil, err
	}
	return dailyRevenue(st, orgID, location(st, orgID), first, last), nil
}

// RevenueReport adds up the organization's revenue per bucket of group (day, week or month; day when empty) from the day
// from to the day to, both included, in the organization's time zone. Every bucket from the one holding from to the one
// holding to is in the report, also those without payments. A bucket is named by its first day.
func RevenueReport(st *store.Store, orgID, from, to, group string) (Report, error) {
	first, last, err := parseRange(from, to)
	if err != nil {
		return Report{}, err
	}
	if group == "" {
		group = string(GroupDay)
	}
	g := Group(group)
	if !g.Valid() {
		return Report{}, fmt.Errorf("%w: %q", ErrInvalidGroup, group)
	}
	loc := location(st, orgID)
	rep := Report{TimeZone: loc.String(), Group: g, Buckets: []Bucket{}}
	index := map[string]int{}
	for s := bucketStart(first, g); !s.After(last); s = nextBucket(s, g) {
		index[s.Format(time.DateOnly)] = len(rep.Buckets)
		rep.Buckets = append(rep.Buckets, Bucket{Start: s.Format(time.DateOnly), Amounts: map[money.Currency]int64{}})
	}
	for _, d := range dailyRevenue(st, orgID, loc, first, last) {
		day, _ := time.Parse(time.DateOnly, d.Date)
		b := &rep.Buckets[index[bucketStart(day, g).Format(time.DateOnly)]]
		b.Amounts[d.Currency] += d.Amount
		b.Payments += d.Payments
	}
	return rep, nil
}

// parseRange reads from and to, which are days (YYYY-MM-DD), and checks that the range is valid.
func parseRange(from, to string) (time.Time, time.Time, error) {
	start, err := time.Parse(time.DateOnly, from)
	if err != nil {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: from %q", ErrInvalidDate, from)
	}
	last, err := time.Parse(time.DateOnly, to)
	if err != nil {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: to %q", ErrInvalidDate, to)
	}
	if last.Before(start) {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: to is before from", ErrInvalidRange)
	}
	if last.Sub(start) >= MaxDays*24*time.Hour {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: at most %d days", ErrInvalidRange, MaxDays)
	}
	return start, last, nil
}

// location is the organization's time zone. An unknown organization has no time zone of its own, so its days are UTC
// days; the store checks the time zone of every organization it saves.
func location(st *store.Store, orgID string) *time.Location {
	o, ok := st.Org(orgID)
	if !ok {
		return time.UTC
	}
	loc, err := time.LoadLocation(o.TimeZone)
	if err != nil {
		return time.UTC
	}
	return loc
}

// dailyRevenue adds up the succeeded payments per day in loc and currency, from the day first to the day last (both
// included). A payment belongs to the day, in loc, when it was made.
func dailyRevenue(st *store.Store, orgID string, loc *time.Location, first, last time.Time) []DayRevenue {
	from, to := first.Format(time.DateOnly), last.Format(time.DateOnly)
	type key struct {
		day string
		cur money.Currency
	}
	sums := map[key]*DayRevenue{}
	for _, p := range st.Payments(orgID, "") {
		if p.Status != store.PaymentSucceeded {
			continue
		}
		day := p.CreatedAt.In(loc).Format(time.DateOnly)
		if day < from || day > to {
			continue
		}
		k := key{day, p.Currency}
		d, ok := sums[k]
		if !ok {
			d = &DayRevenue{Date: k.day, Currency: k.cur}
			sums[k] = d
		}
		d.Amount += p.Amount
		d.Payments++
	}
	out := make([]DayRevenue, 0, len(sums))
	for _, d := range sums {
		out = append(out, *d)
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Date != out[j].Date {
			return out[i].Date < out[j].Date
		}
		return out[i].Currency < out[j].Currency
	})
	return out
}

// bucketStart is the first day of the bucket that holds day (a UTC calendar day). A week starts on Monday.
func bucketStart(day time.Time, g Group) time.Time {
	switch g {
	case GroupWeek:
		return day.AddDate(0, 0, -(int(day.Weekday()) + 6) % 7)
	case GroupMonth:
		return time.Date(day.Year(), day.Month(), 1, 0, 0, 0, 0, time.UTC)
	}
	return day
}

// nextBucket is the first day of the bucket after the one starting on s.
func nextBucket(s time.Time, g Group) time.Time {
	switch g {
	case GroupWeek:
		return s.AddDate(0, 0, 7)
	case GroupMonth:
		return s.AddDate(0, 1, 0)
	}
	return s.AddDate(0, 0, 1)
}

