	// New York is on standard time (UTC-5) until 2026-03-08 02:00 and on daylight saving time (UTC-4) after that, so
	// 2026-03-08 has 23 hours there.
	pay(100, money.USD, store.PaymentSucceeded, time.Date(2026, 3, 8, 4, 30, 0, 0, time.UTC)) // 2026-03-07 23:30 EST
	pay(200, money.USD, store.PaymentSucceeded, time.Date(2026, 3, 9, 3, 30, 0, 0, time.UTC)) // 2026-03-08 23:30 EDT
	pay(400, money.USD, store.PaymentSucceeded, time.Date(2026, 3, 9, 4, 30, 0, 0, time.UTC)) // 2026-03-09 00:30 EDT
	got, err := Revenue(st, orgID, "2026-03-07", "2026-03-09")
	if err != nil {
		t.Fatal(err)
	}
	want := []DayRevenue{
		{Date: "2026-03-07", Currency: money.USD, Amount: 100, Payments: 1},
		{Date: "2026-03-08", Currency: money.USD, Amount: 200, Payments: 1},
		{Date: "2026-03-09", Currency: money.USD, Amount: 400, Payments: 1},
	}
	if len(got) != len(want) {
		t.Fatalf("Revenue = %+v", got)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("day %d = %+v, want %+v", i, got[i], want[i])
		}
	}
	if got, err := Revenue(st, orgID, "2026-03-08", "2026-03-08"); err != nil || len(got) != 1 || got[0].Amount != 200 {
		t.Fatalf("the 8th alone = %+v, %v", got, err)
	}
}

func TestRevenueReport(t *testing.T) {
	st, orgID, pay := nyOrg(t)
	pay(100, money.USD, store.PaymentSucceeded, time.Date(2026, 3, 8, 4, 30, 0, 0, time.UTC))  // 2026-03-07 23:30 EST
	pay(200, money.USD, store.PaymentSucceeded, time.Date(2026, 3, 9, 3, 30, 0, 0, time.UTC))  // 2026-03-08 23:30 EDT
	pay(400, money.USD, store.PaymentSucceeded, time.Date(2026, 3, 9, 4, 30, 0, 0, time.UTC))  // 2026-03-09 00:30 EDT
	pay(50, money.EUR, store.PaymentSucceeded, time.Date(2026, 3, 9, 16, 0, 0, 0, time.UTC))   // 2026-03-09 12:00 EDT
	pay(999, money.USD, store.PaymentFailed, time.Date(2026, 3, 9, 16, 0, 0, 0, time.UTC))     // failed: left out
	daily := Report{TimeZone: "America/New_York", Group: GroupDay, Buckets: []Bucket{
		{Start: "2026-03-07", Amounts: map[money.Currency]int64{money.USD: 100}, Payments: 1},
		{Start: "2026-03-08", Amounts: map[money.Currency]int64{money.USD: 200}, Payments: 1},
		{Start: "2026-03-09", Amounts: map[money.Currency]int64{money.USD: 400, money.EUR: 50}, Payments: 2},
		{Start: "2026-03-10", Amounts: map[money.Currency]int64{}},
	}}
	for _, c := range []struct {
		name, from, to, group string
		want                  Report
	}{
		{"days", "2026-03-07", "2026-03-10", "day", daily},
		{"default is days", "2026-03-07", "2026-03-10", "", daily},
		{"weeks start on Monday, named before from", "2026-03-07", "2026-03-10", "week", Report{TimeZone: "America/New_York", Group: GroupWeek, Buckets: []Bucket{
			{Start: "2026-03-02", Amounts: map[money.Currency]int64{money.USD: 300}, Payments: 2},
			{Start: "2026-03-09", Amounts: map[money.Currency]int64{money.USD: 400, money.EUR: 50}, Payments: 2},
		}}},
		{"months include empty ones", "2026-02-20", "2026-03-10", "month", Report{TimeZone: "America/New_York", Group: GroupMonth, Buckets: []Bucket{
			{Start: "2026-02-01", Amounts: map[money.Currency]int64{}},
			{Start: "2026-03-01", Amounts: map[money.Currency]int64{money.USD: 700, money.EUR: 50}, Payments: 4},
		}}},
	} {
		got, err := RevenueReport(st, orgID, c.from, c.to, c.group)
		if err != nil {
			t.Fatalf("%s: %v", c.name, err)
		}
		if !reflect.DeepEqual(got, c.want) {
			t.Errorf("%s = %+v, want %+v", c.name, got, c.want)
		}
	}
	if _, err := RevenueReport(st, orgID, "2026-03-07", "2026-03-10", "year"); !errors.Is(err, ErrInvalidGroup) {
		t.Fatalf("group year: %v", err)
	}
}

